import React, { useState } from 'react';
import ApplicantForm from './ApplicantForm';
import ApplicantDashboard from './ApplicantDashboard';
import Chatbot from './Chatbot';
import RecruiterDashboard from './RecruiterDashboard';

function App() {
  const [applicantId, setApplicantId] = useState(null);
  const [isRecruiter, setIsRecruiter] = useState(false);

  return (
    <div className="app-container">
      <h1>QualifyAI</h1>
      <div style={{ marginBottom: 16 }}>
        <button onClick={() => setIsRecruiter(false)} style={{ marginRight: 8 }}>
          Applicant View
        </button>
        <button onClick={() => setIsRecruiter(true)}>
          Recruiter View
        </button>
      </div>
      {isRecruiter ? (
        <RecruiterDashboard />
      ) : !applicantId ? (
        <ApplicantForm onSubmitted={setApplicantId} />
      ) : (
        <>
          <ApplicantDashboard applicantId={applicantId} />
          <Chatbot applicantId={applicantId} />
        </>
      )}
    </div>
  );
}

export default App;
